INSERT INTO public.procedures (slug,name,category,short_description,description,benefits,duration,price,image,featured,sort_order) VALUES ('extensao-de-cilios-brasileiro','Extensão de Cílios Brasileiro','cilios','Aplicação de fios leves e naturais para um olhar mais aberto, iluminado e com efeito delicado.','A Extensão de Cílios Brasileiro é uma técnica que aplica fios finos e levemente curvados sobre os cílios naturais, criando um olhar mais aberto, iluminado e com volume natural. Área do corpo: cílios (pálpebra superior). O resultado é delicado, sem pesar ou parecer artificial, ideal para quem quer acordar com os cílios prontos todos os dias. O procedimento é feito com cola hipoalergênica e fios selecionados de acordo com o formato dos seus olhos.',ARRAY['Olhar mais aberto e iluminado','Volume natural e delicado','Dispensa o uso de máscara de cílios','Fios leves que não pesam nos cílios naturais']::text[],'1h 30min',170,'/__l5e/assets-v1/e98ed44a-2c26-4077-9e55-456754394c01/extensao-cilios-brasileiro.jpg',true,0),('extensao-de-cilios-hibrido','Extensão de Cílios Híbrido','cilios','Técnica mista que une fios clássicos e volume para um olhar mais preenchido, leve e natural.','A Extensão de Cílios Híbrido é uma técnica que combina fios clássicos (um a um) com leques de volume, criando um olhar mais preenchido, definido e com leve densidade sem perder o aspecto natural. Área do corpo: cílios (pálpebra superior). O resultado fica entre o efeito clássico e o volume russo, ideal para quem deseja mais volume do que a extensão tradicional, mas sem o visual muito marcante do volume completo. Os fios são aplicados de acordo com o formato dos seus olhos e com a saúde dos cílios naturais, usando cola hipoalergênica e fios leves.',ARRAY['Olhar mais preenchido e definido','Efeito intermediário entre clássico e volume','Resultado leve e natural','Dispensa o uso de máscara de cílios']::text[],'1h 30min',170,'/__l5e/assets-v1/5059448c-d285-4f9a-9738-b5cb9d7d8e76/extensao-cilios-hibrido.jpg',true,10),('cilios-volume-russo','Extensão de Cílios Russo','cilios','Técnica de extensão com leques de fios ultrafinos para um olhar volumoso, marcante e glamouroso.','A Extensão de Cílios Russo é uma técnica avançada de extensão de cílios que aplica leques de fios ultrafinos e leves sobre cada cílio natural, criando um olhar volumoso, denso e glamouroso. Área do corpo: cílios (pálpebra superior). O resultado é mais marcante e dramático que as técnicas clássica e híbrida, ideal para quem deseja olhos de destaque sem precisar de máscara de cílios no dia a dia. O procedimento é realizado com cola hipoalergênica e fios selecionados de acordo com a saúde e curvatura dos seus cílios naturais, garantindo conforto e durabilidade.',ARRAY['Olhar volumoso, denso e marcante','Efeito glamouroso e duradouro','Dispensa o uso de máscara de cílios','Fios leves que respeitam os cílios naturais']::text[],'1h 30min',180,'/__l5e/assets-v1/14a05f58-3893-4b05-970c-8105e861ed19/cilios-volume-russo.jpg',true,20),('fio-a-fio','Fio a Fio','cilios','Aplicação clássica de fios um a um para um olhar delicado, natural e elegante.','A técnica Fio a Fio é a extensão de cílios clássica que aplica um fio sintético fino sobre cada cílio natural, criando um olhar alongado, delicado e natural. Área do corpo: cílios (pálpebra superior). O resultado valoriza o formato dos olhos sem pesar ou parecer artificial, ideal para quem quer acordar com o olhar pronto todos os dias. O procedimento é feito com cola hipoalergênica e fios selecionados de acordo com a saúde e curvatura dos cílios naturais, garantindo conforto e durabilidade.',ARRAY['Olhar alongado e natural','Fios leves que não pesam nos cílios naturais','Efeito delicado e elegante','Dispensa o uso de máscara de cílios']::text[],'2h',600,'/__l5e/assets-v1/73e0f3c4-4070-4be6-9465-9296d10eb0eb/fio-a-fio.jpg',true,30),('perfuracao-lobulo','Perfuração de Lóbulo','piercing','Perfuração segura do lóbulo da orelha com material descartável e joia hipoalergênica.','A perfuração de lóbulo é um procedimento realizado no lóbulo da orelha com técnica segura, material descartável e esterilizado. A joia utilizada é hipoalergênica, ideal para quem está perfurando pela primeira vez ou trocando acessório. Área do corpo: lóbulo da orelha. O procedimento é rápido, com cuidados de assepsia e orientações pós-procedimento para uma cicatrização tranquila.',ARRAY['Procedimento rápido e seguro','Material descartável e esterilizado','Joia hipoalergênica de primeira colocação','Orientações completas de cuidados pós-procedimento']::text[],'10min',100,'/__l5e/assets-v1/f772b4ce-7f19-4492-bbbb-20bc84a92989/perfuracao-lobulo.jpg',true,40),('perfuracao-helix','Perfuração de Hélix','piercing','Perfuração na cartilagem superior da orelha com material descartável e joia hipoalergênica.','A perfuração de hélix é realizada na cartilagem superior da orelha, criando um ponto de destaque delicado e moderno. O procedimento segue rigorosos cuidados de assepsia, com material descartável e esterilizado, além de joia hipoalergênica para uma cicatrização mais tranquila. Área do corpo: cartilagem da orelha (hélix). Ao final, são passadas orientações completas de cuidados pós-procedimento para garantir a saúde da perfuração.',ARRAY['Perfuração precisa na cartilagem','Material descartável e esterilizado','Joia hipoalergênica de qualidade','Orientações completas de cuidados pós-procedimento']::text[],'20min',90,'/__l5e/assets-v1/43e6add6-196f-4126-aa10-957797d709ae/perfuracao-helix.jpg',true,50),('brow-lamination','Brow Lamination','sobrancelha','Alinhamento dos fios das sobrancelhas para um visual mais disciplinado, volumoso e natural.','O Brow Lamination é um procedimento estético para as sobrancelhas que modela e alinha os fios, deixando-as mais disciplinadas, volumosas e com efeito natural de sobrancelha ''penteada''. A técnica utiliza produtos específicos que relaxam os fios e os fixam na direção desejada. Área do corpo: sobrancelhas. O resultado dura em média algumas semanas e facilita a rotina de maquiagem, dispensando o uso de gel ou máscara para sobrancelhas no dia a dia.',ARRAY['Fios alinhados e disciplinados','Visual mais volumoso e natural','Efeito duradouro por várias semanas','Facilita a rotina de maquiagem']::text[],'1h 20min',120,'/__l5e/assets-v1/a4a1fe84-2154-41c2-8965-9548021499f1/brow-lamination.jpg',true,60),('aplicacao-de-henna','Aplicação de Henna','sobrancelha','Coloração natural das sobrancelhas com henna para fios mais definidos, preenchidos e harmoniosos.','A Aplicação de Henna é um procedimento estético para sobrancelhas que utiliza henna vegetal para colorir a pele e os fios, criando um efeito de sobrancelha mais preenchida, definida e harmoniosa. Área do corpo: sobrancelhas. A técnica é ideal para quem deseja corrigir falhas, dar mais volume visual e uniformizar o formato das sobrancelhas de forma natural e temporária. O resultado dura em média alguns dias na pele e pode permanecer mais tempo nos fios, dependendo do tipo de pele e dos cuidados pós-procedimento.',ARRAY['Sobrancelhas mais preenchidas e definidas','Cor natural que harmoniza com o tom da pele','Correção discreta de falhas e assimetrias','Procedimento rápido e sem dor']::text[],'20min',20,'/__l5e/assets-v1/d835906b-4806-4bf4-a40f-6cde2238d836/aplicacao-henna.jpg',true,70),('design-de-sobrancelhas','Design de Sobrancelhas','sobrancelha','Design personalizado das sobrancelhas para valorizar o formato do rosto e realçar o olhar.','O Design de Sobrancelhas é um procedimento estético que define o formato ideal das sobrancelhas de acordo com as medidas e traços do seu rosto. Área do corpo: sobrancelhas. A técnica inclui a avaliação da simetria facial, marcação precisa e remoção dos fios extras para criar um visual harmonioso e natural. O resultado valoriza o olhar e deixa o rosto mais equilibrado, sem deixar a sobrancelha artificialmente fina. Ideal para quem quer manutenção regular ou preparar as sobrancelhas para outros procedimentos como henna ou micropigmentação.',ARRAY['Formato personalizado para o seu rosto','Olhar mais harmonioso e equilibrado','Resultado natural sem exageros','Preparação ideal para henna ou micropigmentação']::text[],'10min',45,'/__l5e/assets-v1/f6214251-9488-44d6-81f1-9c6119023dc6/design-sobrancelhas.jpg',true,80),('micropigmentacao-labial','Micropigmentação Labial','labios','Pigmentação delicada nos lábios para cor uniforme, efeito natural e lábios mais definidos.','A micropigmentação labial deposita pigmento de forma superficial para realçar o contorno, uniformizar a tonalidade e devolver um aspecto saudável aos lábios. Área do corpo: lábios. A cor é escolhida de acordo com o tom natural e o resultado desejado, priorizando acabamento suave e personalizado. O procedimento inclui avaliação prévia e orientações de cuidado para a cicatrização.',ARRAY['Realça o contorno dos lábios','Ajuda a uniformizar a tonalidade','Efeito natural e personalizado','Praticidade no dia a dia']::text[],'2h',650,'/__l5e/assets-v1/cd9cdf17-dd7a-4c10-b98f-ad9e25d0d74f/micropigmentacao-labial.jpg',true,90),('micropigmentacao-olhos-delineado-inferior','Micropigmentação de Olhos — Delineado Inferior','olhos','Pigmentação delicada junto à linha dos cílios inferiores para realçar o olhar com efeito definido e natural.','A micropigmentação de olhos com delineado inferior deposita pigmento de forma superficial próximo à raiz dos cílios inferiores. A técnica ajuda a dar definição ao olhar e cria um efeito semelhante ao lápis, adaptado ao formato dos olhos e ao resultado desejado. Área do corpo: região dos olhos, junto à linha dos cílios inferiores. Antes do procedimento são avaliados formato, espessura e tonalidade, além das orientações de cuidado e cicatrização.',ARRAY['Realça e define o olhar','Efeito semelhante ao lápis','Mais praticidade na rotina de maquiagem','Traço adaptado ao formato dos olhos']::text[],'1h',300,'/__l5e/assets-v1/c3714ab4-10a7-4d81-a036-94cd1b6a0f16/micropigmentacao-olhos.jpg',true,100),('fox-eyes','Fox Eyes','olhos','Extensão de cílios com efeito alongado no canto externo para um olhar marcante, elegante e levantado.','O Fox Eyes é uma técnica de extensão de cílios que concentra fios mais longos e curvados no canto externo dos olhos, criando um efeito visual alongado, levantado e sofisticado. Área do corpo: cílios (pálpebra superior). O mapeamento é personalizado conforme o formato dos olhos para valorizar o olhar sem pesar. A aplicação é feita com fios leves e cola específica, respeitando a saúde dos cílios naturais.',ARRAY['Efeito alongado e levantado no olhar','Mapeamento personalizado para o formato dos olhos','Visual marcante e elegante','Dispensa o uso de máscara de cílios']::text[],'1h 20min',180,'/__l5e/assets-v1/68bf425f-37c0-4781-b461-d9945272800f/fox-eyes.jpg',true,110),('delineado-a-lapis','Delineado a Lápis','olhos','Pigmentação suave na linha dos cílios para um efeito de lápis delicado, definido e prático.','O Delineado a Lápis é uma técnica de micropigmentação que deposita pigmento suavemente junto à linha dos cílios, criando um efeito semelhante ao lápis de olho. Área do corpo: região dos olhos, próxima à linha dos cílios. O traço é planejado de acordo com o formato dos olhos e a intensidade desejada, buscando realçar o olhar de forma delicada e harmoniosa. Antes do procedimento são avaliados desenho, espessura e tonalidade, além das orientações de cuidado e cicatrização.',ARRAY['Realça a linha dos cílios','Efeito suave semelhante ao lápis','Mais praticidade na rotina de maquiagem','Traço personalizado para cada olhar']::text[],'40min',300,'/__l5e/assets-v1/f6588fc1-b871-4a34-8c3d-10969a46e3d5/delineado-a-lapis.jpg',true,120),('dermaplaning','Dermaplaning','limpeza','Esfoliação facial com lâmina específica para remover células mortas e penugem fina, deixando a pele mais lisa e luminosa.','O Dermaplaning é um procedimento de esfoliação mecânica realizado com uma lâmina específica, deslizada suavemente sobre a pele para remover células mortas e os pelos finos do rosto. Área do corpo: rosto. O cuidado ajuda a melhorar a textura, o viço e a uniformidade da pele, além de facilitar a aplicação de cosméticos e maquiagem. Antes do procedimento, a pele é avaliada para confirmar se a técnica é indicada para você.',ARRAY['Pele mais lisa e macia','Remoção de células mortas e penugem fina','Melhora do viço e da textura','Ajuda na aplicação de cosméticos e maquiagem']::text[],'30min',190,'/__l5e/assets-v1/94f291ed-4107-4ef5-9c9e-cc1be49a5590/dermaplaning.jpg',true,130);
INSERT INTO public.jewelry (name,description,image,sort_order) VALUES ('Conjunto Gotas com Zircônias','Conjunto prateado com colar de pingente em formato de gota e brincos coordenados, ambos com zircônias claras. Elegante e luminoso.','/__l5e/assets-v1/e9aa89c9-0d59-4dc2-b0cb-7af07557ebd4/bijuteria-10811.jpg',0),('Conjunto Trevo Delicado','Conjunto prateado com colar de pingente trevo e brincos combinando. Design minimalista com brilho discreto.','/__l5e/assets-v1/486cc298-c4ae-4820-94a2-3a3a5b4dfab5/bijuteria-10817.jpg',10),('Brincos Ponto de Luz','Par de brincos prateados com zircônia redonda em cravação delicada. Um clássico versátil para todos os dias.','/__l5e/assets-v1/44e731fa-4520-4650-a937-fea268bf28c7/bijuteria-10821.jpg',20),('Conjunto Flor de Zircônias','Conjunto prateado com pingente e brincos em formato de flor, formados por zircônias redondas. Feminino e sofisticado.','/__l5e/assets-v1/d0cbfcac-1e56-467c-94a5-0dd84ad333f6/bijuteria-10823.jpg',30),('Colar Coração Vazado','Colar prateado de corrente fina com pingente de coração vazado. Romântico e leve para usar sozinho ou em mix.','/__l5e/assets-v1/728b1b9c-4310-4fe6-a897-1089ce5d1152/bijuteria-10825.jpg',40),('Brinco Argola com Zircônias','Argolas prateadas cravejadas com zircônias claras. Brilho elegante em um formato clássico.','/__l5e/assets-v1/e10f4698-8ea2-43ea-b7ca-cf21a2233a9e/bijuteria-10828.jpg',50),('Colar Medalha de Luz','Colar prateado com pingente redondo de textura radiante e ponto central brilhante. Delicado e moderno.','/__l5e/assets-v1/456caf33-38e5-4d9b-b105-dadf9ed8a542/bijuteria-10830.jpg',60),('Pulseira Medalha Gravada','Pulseira prateada de corrente fina com medalha redonda gravada. Delicada e cheia de significado.','/__l5e/assets-v1/3c3ad782-a3af-4429-9514-037bf1dc6375/bijuteria-10835.jpg',70),('Pulseira Elos Ovais','Pulseira prateada com elos ovais alongados e fecho mosquetão. Clássica e versátil, do casual ao elegante.','/__l5e/assets-v1/d46a19a8-4d65-452f-88a6-9004403fa89e/bijuteria-10838.jpg',80),('Anel Disco Texturizado','Anel prateado com disco redondo texturizado que reflete a luz em leque. Estilo marcante e contemporâneo.','/__l5e/assets-v1/f5726ce9-06b4-4ea0-91d6-2191a2998676/bijuteria-10840.jpg',90),('Bracelete Fio Cruzado','Bracelete prateado de fio duplo com cruzamento central. Design limpo que abraça o pulso com leveza.','/__l5e/assets-v1/14d35937-a9af-4f29-b48e-fde0053a0ebc/bijuteria-10843.jpg',100),('Anel Solitário','Anel prateado solitário com zircônia brilhante em cravação alta. O clássico que nunca sai de moda.','/__l5e/assets-v1/93e2b7b3-7917-4c9c-9495-e880b273b180/bijuteria-10845.jpg',110),('Pulseira Elos Retangulares','Pulseira prateada com elos retangulares vazados. Visual moderno que acompanha você em todos os momentos.','/__l5e/assets-v1/56921a31-8a92-4d0f-a31a-64a322ad06bc/bijuteria-10848.jpg',120),('Anel Falange Círculos','Anel de falange prateado com dois círculos vazados em voltas delicadas. Perfeito para compor mix de anéis.','/__l5e/assets-v1/3a45ef1d-5561-4257-a832-17aa6c97a235/bijuteria-10848.jpg',130);